  ["d33b57a5a3287049"] = { "%s geme.", "." },
  ["d34146fb4cffcc9d"] = { "Ci sono due miniere ad Alterac: la Miniera di Ferrofondo, in territorio dell'⟦Alliance=Alleanza⟧, e la Miniera di Dentefreddo, in territorio dell'⟦Horde=Orda⟧. Entrambe sono ricche di minerali, e in passato servivano a immagazzinare le scorte in eccesso.\n\nOra queste miniere sono contese senza sosta dall'⟦Horde=Orda⟧, dall'⟦Alliance=Alleanza⟧ e dagli abitanti del luogo.", "." },
  ["d343319736d58496"] = { "Cerca la Hall of the Brave nella ⟦Valley of Honor=Valle dell'Onore⟧ e parla con ⟦Grezz Ragefist=Spazzy Pugnocrudele⟧. Fagli sapere che farò rapporto dopo il mio turno qui.", "." },
  ["d34cdc39cef759a7"] = { "Ti serve un'arma, viandante? Non troverai una lama migliore da nessuna parte, te lo assicuro.", "." },
  ["d3564fb521f9ab41"] = { "Venite a me, veri credenti, e scoprite che cosa vi riserva il futuro!", "." },
  ["d35d8995dd5667d4"] = { "Mille anni fa, quando finì la Guerra delle Sabbie Mobili, tre dei nostri si sacrificarono e trattennero i Qiraji dentro queste sale mentre ⟦Anachronos=Anacronos⟧ e Staghelm sigillavano ⟦Ahn'Qiraj=Ahn'qiraj⟧.\n\nOgnuno di noi giurò di cercare Merithra, Arygos e Caelestrasz, se mai il Vallo dello Scarabeo fosse caduto.\n\nE il Vallo è caduto... e così eccoci qui.", "." },
  ["d363ea4f70233843"] = { "Per Kalimdor!", "." },
  ["d37193b3d2e1da56"] = { "Ben <trovato/trovata>, amico. Sono l'ufficiale Pureheart, e ho l'orgoglio di far parte di un'organizzazione diffusa in tutto il mondo e nota come ⟦Argent Dawn=Alba d'Argento⟧. La nostra causa è semplice: combattere con rapidità e senza pietà ogni forma di male che emerga su Azeroth. Non siamo un organismo politico, né vogliamo mai diventarlo. Per questo consideriamo amiche sia l'⟦Alliance=Alleanza⟧ sia l'⟦Horde=Orda⟧: amiche nella causa di estirpare il male!\n\nPer l'Alba, <fratello/sorella> <mio/mia>!", "." },
  ["d37358a8a6e18bff"] = { "Scommetto che l'ho lasciato nella tenda!", "." },
  ["d37fee43db118da1"] = { "Ho perso la mia ⟦Zandalar Madcap's Tunic=Giubba degli Scriteriati degli Zandalari⟧ e me ne serve una nuova, Falthir.", "." },
  ["d388dda45a3b8fc0"] = { "%s lancia l'allarme!", "." },
  ["d38906b13db67a30"] = { "Posso insegnarti i segreti di ⟦Skeletal Horse Riding=Cavalca-Cavallo Scheletrico⟧, se hai abbastanza oro per pagare la lezione!", "." },
  ["d392b1f7950cf98a"] = { "Al lavoro, cani! Spaccatevi la schiena!", "." },
  ["d39b3444257cac7c"] = { "È bene che tu mi serva con tanta fedeltà. Presto tutti serviranno il Re dei Lich... e alla fine avrai la tua ricompensa, purché tu non vacilli.", "." },
  ["d39d305923a0a17e"] = { "Mi hai davvero impressionato, Gerard. Pensavo fossi solo chiacchiere, ma vedo che mi sbagliavo.", "." },
  ["d39d858c244c05af"] = { "Mi dispiace, {name}, ma non do lezioni ai principianti. Parla piuttosto con ⟦Milla Fairancora=Milla Ferancora⟧, alla ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus. Lei può aiutarti a recuperare il tempo perduto.", "." },
  ["d3b33523e87491e8"] = { "Noi venire distruggere piccoletti!", "." },
  ["d3ba96cec1ae21f5"] = { "Dove sono i tuoi dèi adesso? DOVE, SERVITORE?", "." },
  ["d3cbf7702babc5c8"] = { "%s sputa sul cadavere del fanatico caduto.", "." },
  ["d3cccba5dd162ef7"] = { "Ho finito. La pergamena è pronta. Ora torna da Gorzeeki...", "." },
  ["d3cf21e9bb9205c1"] = { "La torta di ciliegie è il mio cibo preferitissimo di tutta Azeroth.", "." },
  ["d3d6202ada6b18df"] = { "Gli Spiriti del Vento ci hanno abbandonati.\n\nOra restano solo echi senza mente. Sta' in guardia, però. Questi venti non sono né benevoli né gentili.", "." },
  ["d3dcfef744adb4db"] = { "Questa foresta può confondere le idee! Sta' attent<o/a> là fuori.", "." },
  ["d3eeda5f3a0b2862"] = { "CHI OSA?! Sarai <distrutto/distrutta>!", "." },
  ["d3f12fac7367f76d"] = { "Ti aspetti che io tremi davanti alla possente legione di {name}?\n\nPer me non sei niente. Meno di niente. Se avessi desiderato la tua testa, mi sarebbe stata portata su una picca.\n\nHai commesso l'errore che commettono tutti i mortali.\n\n<⟦Lord Victor Nefarius=Victor Nefarius⟧ sospira.>\n\nIl tempo gioca strani scherzi a chi lo usa come moneta.", "." },
  ["d3f1e429083eeac8"] = { "Cittadini dell'⟦Alliance=Alleanza⟧, il Signore di ⟦Blackrock=Roccianera⟧ è caduto! Nefarian è stato sconfitto dalla forza congiunta di {name} e dei suoi alleati!", "." },
  ["d3f65b30dd8cd8e4"] = { "Devi avere una reputazione Amichevole con gli umani di ⟦Stormwind=Roccavento⟧ prima che ti insegni l'equitazione, {class}.", "." },
  ["d3f6d19cb5f7a1da"] = { "Il Blastenheimer 5000 Ultra Cannon è un congegno di lancio monoposto all'avanguardia. Scaglia il suo carico a una velocità prossima a quella di un drago, ed è l'orgoglio della famiglia Blastenheimer, famosa in tutto il mondo per le sue imprese aeronautiche e combustibili!\n\nSe vuoi farti lanciare nei cieli e volare <libero/libera> come un uccello, cerca ⟦Maxima Blastenheimer=Maxima Scoppiamicce⟧ sul margine meridionale dell'⟦Hunter Rise=Altura dei Cacciatori⟧ di Picco del Tuono. Ti punterà verso il bersaglio lontano a sud, sul ⟦Stonebull Lake=Lago Toro di Pietra⟧!", "." },
  ["d3f88093dca3b603"] = { "La nostra punizione è anche la nostra benedizione.", "." },
